package com.hbm.client.solarboiler;
import com.hbm.client.model.*;import com.hbm.machine.solarboiler.SolarBoilerBlockEntity;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Exact sourceBase OBJ,yaw and delayed mirror4-face additive focus columns; no animation or heat invented. */
public final class SolarBoilerRenderer implements BlockEntityRenderer<SolarBoilerBlockEntity> {
 static final ResourceLocation MODEL=ResourceLocation.parse("hbm:models/machines/solar_boiler.obj"),TEXTURE=ResourceLocation.parse("hbm:textures/models/machines/solar_boiler.png");public SolarBoilerRenderer(BlockEntityRendererProvider.Context context){}
 static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),MODEL);}static void base(PoseStack pose,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.render(mesh(),pose,buffers.getBuffer(RenderType.entityCutout(TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR,WavefrontMesh.legacyPart("Base"));}
 @Override public void render(SolarBoilerBlockEntity boiler,float partial,PoseStack pose,MultiBufferSource buffers,int light,int overlay){float yaw=switch(DummyableBlock.facing(boiler.getBlockState())){case NORTH->90;case WEST->180;case SOUTH->270;default->0;};LegacyContactShadows.render(boiler,mesh(),new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.toRadians(yaw)),pose,buffers);pose.pushPose();pose.translate(.5,0,.5);pose.pushPose();pose.mulPose(Axis.YP.rotationDegrees(yaw));base(pose,buffers,light,overlay);pose.popPose();if(Minecraft.useFancyGraphics()){var consumer=buffers.getBuffer(SolarBeamRenderTypes.BEAM);int count=0;for(var mirror:boiler.secondary){if(++count>SolarBoilerClient.beamLimit())break;var origin=boiler.getBlockPos();int dx=origin.getX()-mirror.getX(),dy=origin.getY()-mirror.getY(),dz=origin.getZ()-mirror.getZ();double distance=Math.sqrt((double)dx*dx+(double)dy*dy+(double)dz*dz),pitch=Math.toDegrees(-Math.asin((dy+.5)/distance))+90,yawBeam=Math.toDegrees(-Math.atan2(dz,dx))+180;pose.pushPose();pose.translate(-dx,-dy,-dz);pose.translate(0,1,0);pose.mulPose(Axis.YP.rotationDegrees((float)yawBeam));pose.mulPose(Axis.ZP.rotationDegrees((float)pitch));pose.translate(0,-1,0);float d=(float)distance;float[][][] faces={{{.5F,1.0625F,.5F},{.5F,1.0625F,-.5F},{.5F,d,-.5F},{.5F,d,.5F}},{{-.5F,1.0625F,.5F},{-.5F,1.0625F,-.5F},{-.5F,d,-.5F},{-.5F,d,.5F}},{{.5F,1.0625F,.5F},{-.5F,1.0625F,.5F},{-.5F,d,.5F},{.5F,d,.5F}},{{.5F,1.0625F,-.5F},{-.5F,1.0625F,-.5F},{-.5F,d,-.5F},{.5F,d,-.5F}}};for(var face:faces)for(int vertex=0;vertex<4;vertex++){var p=face[vertex];consumer.addVertex(pose.last(),p[0],p[1],p[2]).setColor(1,1,1,vertex<2?.01F:.005F);}pose.popPose();}}pose.popPose();}
 @Override public boolean shouldRenderOffScreen(SolarBoilerBlockEntity boiler){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(SolarBoilerBlockEntity boiler){var p=boiler.getBlockPos();return new AABB(p.getX()-1,p.getY(),p.getZ()-1,p.getX()+2,p.getY()+3,p.getZ()+2);}
}
